import React from 'react';
import MainHeading from '../../Components/Heading/MainHeading';
import NavBar from '../../Components/NavBar/NavBar';
import big from "./back.mp4"
import "./home.css"


function Home() {
  return (
    <>
    <div className="relative w-full h-screen">
    {/* Background video */}
    <video
      className="absolute top-0 left-0 w-full h-full object-cover"
      autoPlay
      loop
      muted
      >
      <source src={big} type="video/mp4" />
      Your browser does not support the video tag.
    </video>

    {/* Overlay content */}
      <NavBar className="z-20"/>
    <div className="relative z-10 flex items-center justify-center w-full h-full bg-black bg-opacity-50">
      <h1 className="text-white text-4xl font-bold">Welcome to My Website</h1>
    </div>
  </div>
      </>
  );
}

export default Home;
